/**
 * The contract `file-picker.tsx` (native) and `file-picker.web.tsx` implement.
 *
 * Its own module for the usual reason — Metro resolves `./file-picker` to the
 * `.web.tsx` file on web, so that file cannot import the shared pieces from
 * `./file-picker` without importing itself.
 */
import type { ReactNode } from "react";
import type { ButtonProps } from "@/components/ui/button";

/**
 * One picked file. Plain data rather than the DOM's `File`, which native does
 * not have: a string and a `Uint8Array` exist on both platforms.
 */
export type PickedFile = {
  name: string;
  /**
   * Where the file sits inside a picked folder, the folder's own name first:
   * `my-skill/assets/logo.png`. Outside a folder pick it is `name`.
   */
  path: string;
  /** The MIME type, when the platform knows it; `""` when it does not. */
  type: string;
  /** The file decoded as text. `""` when `read` is `"bytes"`, which decodes nothing. */
  text: string;
  /** The file as it is on disk. Only there when `read` is `"bytes"`. */
  bytes?: Uint8Array;
};

type FilePickerCommonProps = {
  /**
   * e.g. `"application/json,.json"`. Advisory on the dialog, which lets the user
   * pick "All files", so the web half also applies it to what comes back — to a
   * pick and to a drop alike. A file that does not match is skipped, never read.
   */
  accept?: string | undefined;
  /**
   * Take several files per pick: the dialog allows a multi-select and a drop
   * keeps every file. Off, a pick is one file and a drop keeps the first one
   * `accept` allows.
   */
  multiple?: boolean | undefined;
  /**
   * What to read from each file. `text` (the default) decodes it, which is right
   * for JSON or Markdown and corrupts a `.zip` or an image. `bytes` hands back
   * the file undecoded as `bytes`, and leaves `text` empty.
   *
   * `onPick` only ever carries text and a name, so take `bytes` with `onPickMany`.
   */
  read?: "text" | "bytes" | undefined;
  /**
   * Pick a folder and everything under it instead of files: the dialog chooses
   * a folder, a dropped folder is walked, and each file reports where it sat as
   * its `path`. A folder is several files, so every one `accept` allows is kept
   * whether or not `multiple` is set — and since only `onPickMany` carries a
   * `path`, that is the callback to give. Web only.
   */
  directory?: boolean | undefined;
  /** What is being picked. On the zone it is the visible heading; on the button, the accessible name. */
  label: string;
};

/**
 * One of `onPick` and `onPickMany` is required, and both may be given.
 * `onPickMany` wins when it is there; `onPick` alone is called once per file, so
 * a caller that handles files one at a time needs nothing new to take several.
 */
type FilePickerCallbacks =
  | {
      /**
       * Handed the picked file's decoded text, never the `File` object itself.
       * `File` is DOM-only, so a contract carrying one could not be implemented on
       * native. A screen that wants the bytes, the type or the path takes
       * `onPickMany`, whose `PickedFile` has them. With `multiple` and no
       * `onPickMany`, called once per file, in pick order.
       */
      onPick: (text: string, fileName: string) => void;
      /**
       * Called once per pick with every file in it, in pick order — one file
       * without `multiple`. Given, `onPick` is not called at all.
       */
      onPickMany?: ((files: PickedFile[]) => void) | undefined;
    }
  | {
      onPick?: ((text: string, fileName: string) => void) | undefined;
      onPickMany: (files: PickedFile[]) => void;
    };

export type FilePickerProps = FilePickerCommonProps &
  FilePickerCallbacks & {
    /** The zone's second line, under `label`: what to drop, or where it goes. */
    hint?: string | undefined;
  };

/**
 * The same picker as a `Button`, for where a drop zone does not fit — a page
 * header's actions, a toolbar. It still takes a drop onto itself.
 *
 * A component of its own rather than a `variant="button"` on `FilePicker`,
 * because `variant` and `size` are the `Button`'s, forwarded as they are, and a
 * prop cannot mean both the button's look and which of two shapes to draw.
 */
export type FilePickerButtonProps = FilePickerCommonProps &
  FilePickerCallbacks &
  Pick<ButtonProps, "variant" | "size"> & {
    /**
     * Drawn before the label, or alone at an `icon*` size, where `label` is only
     * the accessible name. Pass a bare `<Upload />`; the button sizes and
     * colours it. Defaults to the upload icon.
     */
    icon?: ReactNode | undefined;
    className?: string | undefined;
  };

/**
 * Whether `file` is one `accept` allows, by the rules the `<input accept>`
 * attribute uses: `.ext` matches the name's ending, `type/*` the MIME type's
 * first half, and anything else the whole MIME type — all ignoring case. An
 * empty or absent `accept` allows everything.
 *
 * Here rather than in the web half so the rule has one home. It takes a name
 * and a type rather than a `File`, which native does not have.
 */
export function acceptsFile(accept: string | undefined, file: { name: string; type: string }) {
  const tokens = (accept ?? "")
    .split(",")
    .map((token) => token.trim().toLowerCase())
    .filter(Boolean);
  if (tokens.length === 0) return true;
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return tokens.some((token) => {
    if (token.startsWith(".")) return name.endsWith(token);
    if (token.endsWith("/*")) return type.startsWith(token.slice(0, -1));
    return type === token;
  });
}

/**
 * The native file picker — a placeholder, not an implementation.
 *
 * **This half does not pick a file.** Reading one off web needs
 * `expo-document-picker` and a file-system read for the URI it returns, both of
 * which are app-level choices with their own permission flow — so rather than
 * ship a drop zone that silently opens nothing, this says so on screen and
 * neither `onPick` nor `onPickMany` is ever called. `multiple`, `accept`, `read`
 * and `directory` are taken so a shared call site typechecks, and do nothing
 * here; an implementation would hand the first two to `expo-document-picker` as
 * its `multiple` and `type`, can filter what comes back with `acceptsFile` the
 * way the web half does, and fills `bytes` as a `Uint8Array` for `read="bytes"`.
 * `directory` is web only: that picker has no folder mode. Replace
 * this file in your app once those are wired up; `file-picker-base.ts` is the
 * contract to implement, and `file-picker.web.tsx` is a working reference for
 * the shape.
 *
 * `FilePickerButton` is the same placeholder as a `Button`: drawn with the look
 * it was given, named by `label`, and disabled, with the reason as its
 * accessibility hint. An icon-sized button has no room to say it on screen.
 */
import { Text, View } from "react-native";
import { Button } from "@/components/ui/button";
import type { FilePickerButtonProps, FilePickerProps } from "@/components/ui/file-picker-base";
import { Upload } from "@/components/ui/icons";

const UNAVAILABLE = "Picking a file is only available on the web app.";

export function FilePicker({ label }: FilePickerProps) {
  return (
    <View className="w-full flex-col items-center gap-2 rounded-xl border-2 border-dashed border-muted-foreground/25 px-6 py-12">
      <Upload className="h-8 w-8 text-muted-foreground" />
      <Text className="text-center text-sm font-medium text-foreground">{label}</Text>
      <Text className="text-center text-xs text-muted-foreground">{UNAVAILABLE}</Text>
    </View>
  );
}

export function FilePickerButton({
  label,
  icon = <Upload />,
  variant,
  size,
  className,
}: FilePickerButtonProps) {
  const iconOnly = typeof size === "string" && size.startsWith("icon");
  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      disabled
      aria-label={label}
      accessibilityHint={UNAVAILABLE}
    >
      {icon}
      {iconOnly ? null : label}
    </Button>
  );
}

/**
 * The web file picker: a drop zone, or a button, over a hidden `<input type="file">`.
 *
 * Both are DOM-only, which is why this is a `.web.tsx`. The caller never sees a
 * `File` — it gets the decoded text, or the bytes — so the calling screen stays
 * shared.
 */
import { type DragEvent, type ReactNode, useRef, useState } from "react";
import { Text } from "react-native";
import { buttonTextVariants, buttonVariants } from "@/components/ui/button";
import {
  acceptsFile,
  type FilePickerButtonProps,
  type FilePickerProps,
  type PickedFile,
} from "@/components/ui/file-picker-base";
import { Upload } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

type PickOptions = Pick<
  FilePickerProps,
  "onPick" | "onPickMany" | "accept" | "multiple" | "read" | "directory"
>;

/** A file and where it sat in the folder it came from. */
type Found = { file: File; path: string };

/**
 * What makes the dialog choose a folder. Spread onto the input rather than
 * written as a prop because React's typings do not know the attribute, and as a
 * string because React drops an unknown attribute whose value is `true`.
 */
const DIRECTORY_INPUT: Record<string, string> = { webkitdirectory: "" };

/**
 * A pick from the dialog. In a folder pick the browser fills
 * `webkitRelativePath` — the folder's own name first — and leaves it empty
 * otherwise, which is the `path` rule: the place in the folder, or the name.
 */
function fromList(list: FileList | null | undefined): Found[] {
  return Array.from(list ?? [], (file) => ({ file, path: file.webkitRelativePath || file.name }));
}

/**
 * Everything under the dropped entries, depth first, in the order the browser
 * lists them. A dropped folder arrives in `dataTransfer.files` as one
 * unreadable `File` with no children, so the tree has to be walked through its
 * entries. An entry's `fullPath` starts with a slash and then matches what the
 * dialog would report, so a drop and a pick give the same `path`.
 */
async function walk(entries: FileSystemEntry[]): Promise<Found[]> {
  const found: Found[] = [];
  for (const entry of entries) {
    if (entry.isFile) {
      const file = await new Promise<File>((resolve, reject) =>
        (entry as FileSystemFileEntry).file(resolve, reject),
      );
      found.push({ file, path: entry.fullPath.replace(/^\//, "") });
    } else if (entry.isDirectory) {
      const reader = (entry as FileSystemDirectoryEntry).createReader();
      // `readEntries` hands back a batch at a time — a hundred, in Chrome — and
      // an empty one when it is done, so one call would cut a big folder short.
      for (;;) {
        const batch = await new Promise<FileSystemEntry[]>((resolve, reject) =>
          reader.readEntries(resolve, reject),
        );
        if (batch.length === 0) break;
        found.push(...(await walk(batch)));
      }
    }
  }
  return found;
}

/**
 * The picking, apart from the look: the hidden input, what a click and a drop
 * do, and whether something is being dragged over. The zone and the button are
 * two faces on this one hook, so they cannot disagree about what a pick is.
 */
function useFilePick({ onPick, onPickMany, accept, multiple, read, directory }: PickOptions) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);

  async function take(found: Found[]) {
    // `accept` is only advisory on the dialog, ignored by a folder dialog and
    // not applied to a drop at all, so it is applied here, to all three.
    const allowed = found.filter(({ file }) => acceptsFile(accept, file));
    // A folder is every file in it; `multiple` is about picking files.
    const files = multiple || directory ? allowed : allowed.slice(0, 1);
    if (files.length === 0) return;
    const picked = await Promise.all(
      files.map(async ({ file, path }): Promise<PickedFile> => {
        const base = { name: file.name, path, type: file.type };
        // One or the other: decoding a `.zip` to hand back a string nobody
        // reads would cost its whole size again.
        return read === "bytes"
          ? { ...base, text: "", bytes: new Uint8Array(await file.arrayBuffer()) }
          : { ...base, text: await file.text() };
      }),
    );
    if (onPickMany) onPickMany(picked);
    else for (const file of picked) onPick?.(file.text, file.name);
  }

  const trigger = {
    type: "button" as const,
    onClick: () => inputRef.current?.click(),
    onDragOver: (e: DragEvent) => {
      e.preventDefault();
      setDragging(true);
    },
    onDragLeave: () => setDragging(false),
    onDrop: (e: DragEvent) => {
      e.preventDefault();
      setDragging(false);
      // Read before the first `await` either way: a drop's files and items are
      // gone once the event returns.
      if (directory) {
        const entries = Array.from(e.dataTransfer.items, (item) => item.webkitGetAsEntry());
        void walk(entries.filter((entry) => entry !== null)).then(take);
      } else {
        void take(fromList(e.dataTransfer.files));
      }
    },
  };

  const input = (
    <input
      ref={inputRef}
      type="file"
      {...(accept ? { accept } : {})}
      {...(multiple ? { multiple: true } : {})}
      {...(directory ? DIRECTORY_INPUT : {})}
      className="hidden"
      onChange={(e) => {
        // Copied before the value is reset, which empties the input's `FileList`.
        void take(fromList(e.target.files));
        // Allow re-selecting the same file after a reset.
        e.target.value = "";
      }}
    />
  );

  return { trigger, input, dragging };
}

export function FilePicker({ label, hint, ...options }: FilePickerProps) {
  const { trigger, input, dragging } = useFilePick(options);

  return (
    <>
      <button
        {...trigger}
        className={cn(
          "flex w-full flex-col items-center gap-2 rounded-xl border-2 border-dashed px-6 py-12 text-center transition-colors",
          dragging
            ? "border-primary bg-primary/5"
            : "border-muted-foreground/25 hover:border-muted-foreground/50",
        )}
      >
        <Upload className="h-8 w-8 text-muted-foreground" />
        <Text className="font-medium text-sm">{label}</Text>
        {hint ? <Text className="text-xs text-muted-foreground">{hint}</Text> : null}
      </button>
      {input}
    </>
  );
}

export function FilePickerButton({
  label,
  icon = <Upload />,
  variant,
  size,
  className,
  ...options
}: FilePickerButtonProps) {
  const { trigger, input, dragging } = useFilePick(options);
  // At an icon size the square has no room for words, so `label` is the name alone.
  const iconOnly = typeof size === "string" && size.startsWith("icon");
  let content: ReactNode = icon;
  if (!iconOnly) {
    content = (
      <>
        {icon}
        <Text className={buttonTextVariants({ variant, size })}>{label}</Text>
      </>
    );
  }

  return (
    <>
      {/* `buttonVariants` on a plain `<button>` rather than `Button`: in an Expo web app `Button`
          is a `Pressable`, which drops the drag handlers a drop needs. */}
      <button
        {...trigger}
        aria-label={label}
        className={cn(
          buttonVariants({ variant, size }),
          dragging && "ring-2 ring-primary ring-offset-2 ring-offset-background",
          className,
        )}
      >
        {content}
      </button>
      {input}
    </>
  );
}
